"""
Turn a video (or a set of its key frames) into a WLED light recipe.

Pipeline:
    video -> key frames (video_frames.py / ffmpeg)
          -> per-frame FOUR-EDGE colors (color_edges.py) + dominant colors
          -> one time-ordered multi-color palette (the video's color progression)
          -> per-edge color sequences (mapped to the 4 backlight segments)
          -> a recipe dict ready for apply_recipe.py / apply_video_recipe.py

Usage:
    python3 scripts/analyze_video.py <video_url_or_path> --scene "Sunset Ocean"
    python3 scripts/analyze_video.py --frames f1.jpg f2.jpg f3.jpg --scene "Aurora"
    python3 scripts/analyze_video.py clip.mp4 --count 10 --mode scene --json

Output: JSON with {success, scene, recipe, frames_used, edge_colors}
"""
import json
import os
import sys

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
sys.path.insert(0, SCRIPT_DIR)

from analyze_image import (load_image, analyze_colors, rgb_to_hsv, build_wled_palette,
                           load_config, suggest_recipe)
from color_edges import extract_edge_colors, EDGE_ORDER
from resolve_fx import load_effects_for_host

MAX_PALETTE_STOPS = 12      # WLED custom palettes are small; keep it lean
HUE_SIMILAR = 22            # degrees; consecutive colors closer than this are merged
RGB_SIMILAR = 36


def _effects_list(config=None):
    cfg = config or load_config()
    host = (cfg.get("wled", {}) or {}).get("ip") or ""
    cache = os.path.join(SCRIPT_DIR, ".wled_effects_cache.json")
    return load_effects_for_host(host or None, cache_path=cache)


def _to_rgb(entry):
    if isinstance(entry, dict):
        if "rgb" in entry:
            return list(entry["rgb"])
        if "hex" in entry:
            h = entry["hex"].lstrip("#")
            return [int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)]
    return list(entry)


def _similar(a, b):
    ha, _, _ = rgb_to_hsv(*a)
    hb, _, _ = rgb_to_hsv(*b)
    dh = min(abs(ha - hb), 360 - abs(ha - hb))
    drgb = max(abs(a[i] - b[i]) for i in range(3))
    return dh < HUE_SIMILAR and drgb < RGB_SIMILAR


def dedupe_sequence(rgbs):
    """Collapse consecutive near-identical colors, keeping time order."""
    out = []
    for rgb in rgbs:
        rgb = [int(max(0, min(255, c))) for c in rgb]
        if not out or not _similar(out[-1], rgb):
            out.append(rgb)
    return out


def _cap_with_even_spread(seq, limit):
    """Thin a sequence to `limit` entries while preserving first/last."""
    if len(seq) <= limit:
        return seq
    if limit <= 2:
        return [seq[0], seq[-1]][:limit]
    step = (len(seq) - 1) / float(limit - 1)
    picked = [seq[min(len(seq) - 1, int(round(i * step)))] for i in range(limit)]
    out = []
    for c in picked:
        if not out or out[-1] != c:
            out.append(c)
    return out


def _pick_distinct(colors, n=3):
    """Pick up to n visually distinct colors from a list (order preserved)."""
    picked = []
    for c in colors:
        if not any(_similar(c, p) for p in picked):
            picked.append(c)
        if len(picked) >= n:
            break
    for c in colors:
        if len(picked) >= n:
            break
        if c not in picked:
            picked.append(c)
    while picked and len(picked) < n:
        picked.append(picked[-1])
    return picked[:n]


def _representative_edge_color(samples):
    """Most common (quantized) color across a set of {rgb, ratio} samples."""
    if not samples:
        return [128, 128, 128]
    weight = {}
    raw = {}
    for s in samples:
        rgb = list(s["rgb"])
        key = tuple(c // 32 for c in rgb)
        weight[key] = weight.get(key, 0.0) + float(s.get("ratio", 1.0))
        raw.setdefault(key, []).append(rgb)
    best = max(weight, key=weight.get)
    group = raw[best]
    return [int(sum(c[i] for c in group) / len(group)) for i in range(3)]


def analyze_video_frames(frame_paths, scene_name="Video Scene", config=None,
                         band_ratio=0.12):
    """Core analysis: frames -> recipe. Pure computation, no device writes."""
    config = config or load_config()
    color_cfg = config.get("color_analysis", {})
    stop_cfg = config.get("video", {}) or {}
    band_ratio = float(stop_cfg.get("edge_band_ratio", band_ratio))

    per_frame = []
    edge_samples = {e: [] for e in EDGE_ORDER}
    errors = []

    for path in frame_paths:
        try:
            img = load_image(path, validate_quality=False)
            dom = analyze_colors(
                img,
                num_colors=color_cfg.get("num_colors", 5),
                min_saturation=color_cfg.get("min_saturation", 30),
                min_brightness=color_cfg.get("min_brightness", 20),
                avoid_overdark=color_cfg.get("avoid_overdark", True),
            )
            edges = extract_edge_colors(img, band_ratio=band_ratio, stops=3)["edges"]
            per_frame.append({"path": path, "dominant": dom, "edges": edges})
            for e in EDGE_ORDER:
                edge_samples[e].append({"rgb": edges[e]["rgb"], "ratio": edges[e]["ratio"]})
        except Exception as exc:
            errors.append({"frame": path, "error": str(exc)})

    if not per_frame:
        return {"success": False, "message": "No frames could be analyzed", "errors": errors}

    # Time-ordered progression: dominant color of each frame, in play order.
    timed = []
    for f in per_frame:
        if f["dominant"]:
            timed.append(_to_rgb(f["dominant"][0]))
    sequence = dedupe_sequence(timed) or [[128, 128, 128]]
    palette_colors = _cap_with_even_spread(sequence, MAX_PALETTE_STOPS)

    # Per-edge time sequences (each edge gets its own colour evolution).
    edge_sequences = {}
    edge_repr = {}
    for e in EDGE_ORDER:
        edge_repr[e] = _representative_edge_color(edge_samples[e])
        seq = dedupe_sequence([_to_rgb(s) for s in edge_samples[e]])
        capped = _cap_with_even_spread(seq, 3)
        edge_sequences[e] = capped if capped else [edge_repr[e]]

    # Three representative colors for the classic `col` array (fallback path).
    distinct_pool = []
    for f in per_frame:
        for c in f["dominant"]:
            distinct_pool.append(_to_rgb(c))
    rep_colors = _pick_distinct(dedupe_sequence(distinct_pool) or sequence, 3)

    # Theme / FX / sliders — reuse the shared, name-resolved logic.
    effects = _effects_list(config)
    color_entries = []
    for i, rgb in enumerate(rep_colors):
        h, s, v = rgb_to_hsv(*rgb)
        color_entries.append({
            "rgb": rgb,
            "hex": "#{:02X}{:02X}{:02X}".format(*rgb),
            "ratio": round(1.0 / len(rep_colors), 4),
            "hsv": {"h": round(h, 1), "s": round(s, 1), "v": round(v, 1)},
        })
    suggestion = suggest_recipe(color_entries, config, effects=effects)

    sx = max(50, min(90, int(suggestion.get("sx", 70))))
    ix = max(80, min(120, int(suggestion.get("ix", 100))))
    bri = max(150, min(200, int(suggestion.get("bri", 180))))

    palette_entries = [{"rgb": c} for c in palette_colors]
    recipe = {
        "name": scene_name,
        "version": "1.0",
        "format": "wled-skills-recipe-v1",
        "source_type": "video",
        "frame_count": len(per_frame),
        "colors": rep_colors,
        "palette_data": build_wled_palette(palette_entries),
        "palette_colors": palette_colors,
        "edge_colors": edge_repr,
        "edge_sequences": edge_sequences,
        "fx": suggestion.get("fx", 12),
        "sx": sx,
        "ix": ix,
        "bri": bri,
        "pal": 0,
        "theme": suggestion.get("theme", "nature"),
        "rationale": (suggestion.get("rationale", "") +
                      " | video time-sequence palette, four-edge mapping").strip(),
        "edge_colors_hex": {e: "#{:02X}{:02X}{:02X}".format(*edge_repr[e]) for e in EDGE_ORDER},
        "palette_colors_hex": ["#{:02X}{:02X}{:02X}".format(*c) for c in palette_colors],
    }

    return {
        "success": True,
        "scene": scene_name,
        "recipe": recipe,
        "frames_used": [os.path.basename(f["path"]) for f in per_frame],
        "frame_count": len(per_frame),
        "edge_colors": edge_repr,
        "edge_colors_hex": recipe["edge_colors_hex"],
        "palette_colors_hex": recipe["palette_colors_hex"],
        "errors": errors,
        "message": "Analyzed {} frames for '{}': {} palette stops, fx={}".format(
            len(per_frame), scene_name, len(palette_colors), recipe["fx"]),
    }


def analyze_video(video, scene_name="Video Scene", count=8, mode="even",
                  config=None, max_width=1280, out_dir=None, keep_frames=True):
    """Extract frames from a video then analyze them."""
    from video_frames import extract_keyframes
    ext = extract_keyframes(video, count=count, mode=mode, out_dir=out_dir,
                            max_width=max_width)
    if not ext.get("success"):
        return ext
    result = analyze_video_frames([f["path"] for f in ext["frames"]], scene_name,
                                  config=config)
    result["video"] = video
    result["video_meta"] = {
        "duration": ext.get("duration"),
        "width": ext.get("width"),
        "height": ext.get("height"),
        "fps": ext.get("fps"),
        "mode": ext.get("mode"),
    }
    if not keep_frames:
        for f in ext["frames"]:
            try:
                os.remove(f["path"])
            except OSError:
                pass
    return result


def main():
    if "--help" in sys.argv or "-h" in sys.argv or len(sys.argv) < 2:
        print(__doc__)
        sys.exit(0)

    scene = "Video Scene"
    count = 8
    mode = "even"
    json_only = False
    frames = []
    video = None
    keep_frames = "--discard-frames" not in sys.argv

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--scene" and i + 1 < len(sys.argv):
            scene = sys.argv[i + 1]; i += 2
        elif arg == "--count" and i + 1 < len(sys.argv):
            count = int(sys.argv[i + 1]); i += 2
        elif arg == "--mode" and i + 1 < len(sys.argv):
            mode = sys.argv[i + 1]; i += 2
        elif arg == "--json":
            json_only = True; i += 1
        elif arg == "--frames":
            i += 1
            while i < len(sys.argv) and not sys.argv[i].startswith("--"):
                frames.append(sys.argv[i]); i += 1
        elif arg == "--discard-frames":
            keep_frames = False; i += 1
        elif not arg.startswith("--") and video is None:
            video = arg; i += 1
        else:
            i += 1

    if frames:
        result = analyze_video_frames(frames, scene)
    elif video:
        result = analyze_video(video, scene, count=count, mode=mode, keep_frames=keep_frames)
    else:
        print(json.dumps({"success": False, "message": "Provide a video path/URL or --frames ..."},
                         ensure_ascii=False))
        sys.exit(1)

    if not json_only and result.get("success"):
        print("Scene: {}".format(scene))
        print("Frames: {}".format(result.get("frame_count")))
        print("Edge colors: {}".format(json.dumps(result.get("edge_colors_hex", {}), ensure_ascii=False)))
        print("Palette: {}".format(", ".join(result.get("palette_colors_hex", []))))
        print("\n--- JSON ---")

    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
